import math


def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Using matrix exponentiation to find the n-th Fibonacci number
        # The Fibonacci number sequence is closely related to the powers of the
        # transformation matrix [[1, 1], [1, 0]].
        T = [[1, 1], [1, 0]]
        result = [[1, 1], [1, 0]]
        power(T, n - 1)
        return result[0][0]


def multiply(A, B, result):
    # Multiply two matrices
    x = result[0][0]
    y = result[0][1]
    z = result[1][0]
    w = result[1][1]
    return [[x * B[0][0] + y * B[0][1], x * B[0][2] + y * B[0][3]],
            [z * B[1][1], w * B[1][1] + (z * B[1][2] + w * B[1][3])]]


def power(A, n):
    # Raise a matrix to the power of n using the exponentiation by squaring method
    if n == 1:
        return A
    elif n % 2:
        return multiply(A, power(A, n // 2), A)
    else:
        B = power(A, n // 2)
        return multiply(B, B, A)

